// Fetches JSON from the data API. In this prototype the "API" is static
// files under public/data (generated by scripts/data/generate.mjs), which
// works on GitHub Pages. On the real site, point API_BASE at the Laravel
// API and keep everything else.

const API_BASE = `${import.meta.env.BASE_URL}data/`

// Each file is fetched at most once per visit. Storing the promise (not the
// result) means two components asking at the same moment share one request.
const cache = new Map<string, Promise<unknown>>()

export function getJson<T>(path: string): Promise<T> {
  let request = cache.get(path) as Promise<T> | undefined
  if (!request) {
    request = fetch(API_BASE + path).then((response) => {
      if (!response.ok) throw new Error(`Could not load ${path} (${response.status})`)
      return response.json() as Promise<T>
    })
    // A failed request is forgotten, so "Try again" really tries again.
    request.catch(() => cache.delete(path))
    cache.set(path, request)
  }
  return request
}
